# ------------------------------------------
# Softmax Function — Documentation & Math
# ------------------------------------------
#
# In both softmax regression and neural networks with softmax outputs, N outputs are generated,
# and one output is selected as the predicted category.
# In both cases, a vector z is generated by a linear function and passed to a softmax function.
#
# The softmax function converts z into a probability distribution.
# After applying softmax, each output is between 0 and 1, and the outputs add up to 1
# (so they can be interpreted as probabilities).
# Larger inputs produce larger output probabilities.
#
# ----------- Softmax Regression -----------
# z_j = w_j · x + b_j    # Linear combination for each class j
#
# Softmax activation:
#   a_j = exp(z_j) / (sum_k exp(z_k))      # for each class j=1...N
#
#   This is the probability that input x belongs to class j.
#
#   a_1 = exp(z_1) / (exp(z_1) + ... + exp(z_N))   # P(y=1|x)
#   ...
#   a_N = exp(z_N) / (exp(z_1) + ... + exp(z_N))   # P(y=N|x)
#
# ---------- Neural Network w/ Softmax -----
# In neural networks, z_j is the output of the last (linear) layer before softmax:
#   z_j = w_j^L · a^{L-1} + b_j^L
#
# The same softmax is applied:
#   a_j = exp(z_j) / (sum_k exp(z_k))
#
# ---------- Vector Notation ---------------
# Output vector a(x) = [P(y=1|x; w, b), ..., P(y=N|x; w, b)]^T
#      = 1 / sum_k(exp(z_k)) * [exp(z_1), ..., exp(z_N)]^T
#
# ------------------------------------------
import numpy as np
import matplotlib.pyplot as plt
import os
os.environ['TF_CPP_MIN_LOG_LEVEL'] = '2'  # or '3' for errors only
import tensorflow as tf
from tensorflow.keras.layers import Dense
from tensorflow.keras import Sequential
from IPython.display import display, Markdown, Latex
from sklearn.datasets import make_blobs
from matplotlib.widgets import Slider
import logging
logging.getLogger('tensorflow').setLevel(logging.ERROR)
tf.autograph.set_verbosity(0)

def my_softmax(z):
    """
    Compute the softmax of a vector z.
    
    Parameters:
        z -- Input vector (1D array)
        
    Returns:
        Softmax probabilities (1D array)
    """
    e_z = np.exp(z)
    return e_z / np.sum(e_z)

def plot_softmax(z):
    """
    Plot the softmax function for a given input vector z.
    
    Parameters:
        z -- Input vector (1D array)
    """
    a = my_softmax(z)
    
    plt.figure(figsize=(10, 6))
    plt.bar(range(len(a)), a, tick_label=[f'Class {i+1}' for i in range(len(a))])
    plt.xlabel('Classes')
    plt.ylabel('Softmax Probability')
    plt.title('Softmax Function Output')
    plt.ylim(0, 1)
    plt.grid(axis='y')
    plt.show()

# --------------------------------------
plot_softmax(np.array([1.0, 2.0, 3.0]))  # Example usage with a sample vector
plot_softmax(np.array([0.5, 1.5, 2.5]))


# --------------------------------------
# Visualizing the Softmax Function with Interactive Sliders
def plot_softmax_interactive():
    """
    Create an interactive plot to visualize the softmax function with sliders.
    """
    fig, ax = plt.subplots(figsize=(10, 6))
    plt.subplots_adjust(bottom=0.25)

    # Initial values for the softmax inputs
    z = np.array([1.0, 2.0, 3.0])

    # Function to update the plot based on slider values
    def update(val):
        z[0] = slider1.val
        z[1] = slider2.val
        z[2] = slider3.val
        a = my_softmax(z)
        ax.clear()
        ax.bar(range(len(a)), a, tick_label=[f'Class {i+1}' for i in range(len(a))])
        ax.set_xlabel('Classes')
        ax.set_ylabel('Softmax Probability')
        ax.set_title('Softmax Function Output')
        ax.set_ylim(0, 1)
        ax.grid(axis='y')
        plt.draw()

    # Create sliders for each input value
    slider_ax1 = plt.axes([0.1, 0.01, 0.65, 0.03])
    slider_ax2 = plt.axes([0.1, 0.05, 0.65, 0.03])
    slider_ax3 = plt.axes([0.1, 0.09, 0.65, 0.03])

    slider1 = Slider(slider_ax1, 'z[0]', -5.0, 5.0, valinit=z[0])
    slider2 = Slider(slider_ax2, 'z[1]', -5.0, 5.0, valinit=z[1])
    slider3 = Slider(slider_ax3, 'z[2]', -5.0, 5.0, valinit=z[2])

    # Attach the update function to the sliders
    slider1.on_changed(update)
    slider2.on_changed(update)
    slider3.on_changed(update)

    # Initial plot
    update(None)

    plt.show()  

plot_softmax_interactive()  # Call the interactive plot function



# --------------------------------------
# Cross-Entropy Loss for Softmax Output
# --------------------------------------
#
# The loss function associated with Softmax regression is the **cross-entropy loss**.
# This measures how well the predicted probability distribution (output of softmax)
# matches the true label (as a one-hot vector).
#
# --- For a single example ---
#
# Let:
#   - a = [a_1, ..., a_N] = softmax outputs (predicted probabilities)
#   - y = target class (integer from 1 to N)
#
# The loss for one example is:
#     L(a, y) = -log(a_y)
#         where a_y is the predicted probability for the true class y
#
# In expanded form:
#     L(a, y) = -log(a_1),  if y == 1
#               ...
#               -log(a_N),  if y == N
#
# Only the output probability corresponding to the true class contributes to the loss.
#
# --- Indicator Function (for general formula) ---
# To write this in a single equation, use an indicator function:
#     1{y == j} = 1 if the true class is j, else 0
#
# --- Average Cost over Dataset (Cost Function) ---
#
# For m examples and N classes:
#     J(w, b) = -(1/m) * sum_{i=1}^m sum_{j=1}^N 1{y^(i) == j} * log(a_j^(i))
#
# - m: number of examples
# - N: number of classes
# - y^(i): target label for example i
# - a_j^(i): predicted probability for class j, example i
#
# In terms of the logits z (before softmax), the formula becomes:
#     J(w, b) = -(1/m) * sum_{i=1}^m sum_{j=1}^N 1{y^(i) == j} * log( exp(z_j^(i)) / sum_k exp(z_k^(i)) )
#
# The cost is the **average** cross-entropy loss over all examples.
#
# ------------------------------------------------
# Recall: In some notation, 'loss' is for one example, while 'cost' is the average over all examples.
# ------------------------------------------------

centers = [[-5, 2], [-2, -2], [1, 2], [5, 2]]
X, y = make_blobs(n_samples = 1000, centers = centers, cluster_std = 1.0, random_state = 20)

model = Sequential([
    Dense(25, activation='relu'),
    Dense(15, activation='relu'),
    Dense(4, activation='softmax')
])

model.compile( loss = tf.keras.losses.SparseCategoricalCrossentropy(),
               optimizer = tf.keras.optimizers.Adam(learning_rate = 0.001),
               metrics = ['accuracy'])
model.fit(X, y, epochs = 10, batch_size = 32, verbose = 1)

p_nonprefered = model.predict( X )
print("Predicted probabilities for non-preferred class:", p_nonprefered[ :2 ])
print("Largest predicted probability for non-preferred class:", np.max(p_nonprefered, axis=1)[:2])
print("Smallest predicted probability for non-preferred class:", np.min(p_nonprefered, axis=1)[:2])

# Preferred: Numerically Stable Softmax and Loss Combination
#
# It is more stable and accurate to combine the softmax activation and the loss function
# during training, rather than applying softmax in the model and then using a separate loss.
# This is the 'preferred' organization for classification tasks.
#
# In this approach:
#   - The final layer should use a linear activation (no softmax).
#   - The loss function should be called with `from_logits=True`.
#
# For example:
# model.compile(loss=tf.keras.losses.SparseCategoricalCrossentropy(from_logits=True), ...)
#
# This informs the loss function to include the softmax operation internally, allowing
# for an optimized and more numerically stable implementation.
#
# Why?
#   - This avoids potential numerical instability from large/small exponentials in softmax.
#   - Combining them allows TensorFlow/Keras to use optimized math under the hood.
#
# For reference:
#   - 'Logits' refers to the raw, unnormalized outputs from the model's last (linear) layer.
#   - The loss function will apply softmax and then calculate cross-entropy in a stable way.
#   - This is the recommended practice for classification tasks in TensorFlow/Keras.

# --------------------------------------

preferred_model = Sequential([
    Dense(25, activation='relu'),
    Dense(15, activation='relu'),
    Dense(4, activation='linear')  # No activation here, logits will be used directly
])
preferred_model.compile(
    loss=tf.keras.losses.SparseCategoricalCrossentropy(from_logits=True),
    optimizer=tf.keras.optimizers.Adam(learning_rate=0.001),
    metrics=['accuracy']
)

preferred_model.fit(X, y, epochs=10, batch_size=32, verbose=1)

# Example usage of the preferred model
p_preferred = preferred_model.predict(X)
print("Predicted logits for preferred model:", p_preferred[:2])
print("Largest predicted logit for preferred class:", np.max(p_preferred, axis=1)[:2])
print("Smallest predicted logit for preferred class:", np.min(p_preferred, axis=1)[:2])
# --------------------------------------

# Visualize both preferred and non-preferred model predictions
def plot_predictions(model, X, title):
    preds = model.predict(X)
    plt.figure(figsize=(10, 6))
    plt.title(title)
    plt.bar(range(len(preds[0])), preds[0])
    plt.xlabel('Classes')
    plt.ylabel('Predicted Probability')
    plt.xticks(range(len(preds[0])), [f'Class {i+1}' for i in range(len(preds[0]))])
    plt.show()
plot_predictions(model, X, "Non-Preferred Model Predictions")
plot_predictions(preferred_model, X, "Preferred Model Predictions")

# --------------------------------------

sm_preferred = tf.nn.softmax(p_preferred, axis=1).numpy()
print("Softmax probabilities for preferred model:", sm_preferred[:2])
print("Largest softmax probability for preferred class:", np.max(sm_preferred, axis=1)[:2])
print("Smallest softmax probability for preferred class:", np.min(sm_preferred, axis=1)[:2])

for i in range(5):
    print(f"Example {i+1} - Non-Preferred Model:")
    print(f"  Predicted Probabilities: {p_nonprefered[i]}")
    print(f"  Largest Probability: {np.max(p_nonprefered[i])}")
    print(f"  Smallest Probability: {np.min(p_nonprefered[i])}")

    print(f"Example {i+1} - Preferred Model:")
    print(f"  Predicted Logits: {p_preferred[i]}")
    print(f"  Largest Logit: {np.max(p_preferred[i])}")
    print(f"  Smallest Logit: {np.min(p_preferred[i])}")